-- =============================================================================
-- V020  billing — the financial effect of orders: invoices, invoice lines,
--       charges (append-only ledger), payments, allocations, tokenised payment
--       methods, annual payment commitments.
-- =============================================================================
-- Voucher rules live in the vouchers schema; billing records money only.
-- Foreign keys that leave this file (core, crm, orders, iam) are in
-- migrations/fk/billing.sql and are assembled into V090. tenant_id -> core.tenants
-- FKs are generated by V090 for every table.
-- Business rules (invoice total recalculation, financial edit lock, uncharge
-- procedure) are V100/V110; only generic touch / append-only triggers are here.
-- =============================================================================

-- ---------------------------------------------------------------- invoices
CREATE TABLE billing.invoices (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    uuid                uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    invoice_number      varchar(60) NOT NULL,
    contact_id          bigint NOT NULL,
    billing_address_id  bigint,
    status              varchar(20) NOT NULL DEFAULT 'draft',
    currency_code       core.currency_code NOT NULL,
    subtotal_amount     core.money_amount NOT NULL DEFAULT 0,
    discount_amount     core.money_amount NOT NULL DEFAULT 0,
    voucher_amount      core.money_amount NOT NULL DEFAULT 0,
    tax_amount          core.money_amount NOT NULL DEFAULT 0,
    total_amount        core.money_amount NOT NULL DEFAULT 0,
    paid_amount         core.money_amount NOT NULL DEFAULT 0,
    balance_amount      core.money_amount GENERATED ALWAYS AS (total_amount - paid_amount) STORED,
    issued_on           date,
    due_on              date,
    paid_on             date,
    external_ref        varchar(120),
    notes               text,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_invoices PRIMARY KEY (id),
    CONSTRAINT uq_invoices__uuid UNIQUE (uuid),
    CONSTRAINT uq_invoices__tenant_id__invoice_number UNIQUE (tenant_id, invoice_number),
    CONSTRAINT ck_invoices__status CHECK (status IN ('draft','issued','partially_paid','paid','overdue','void','written_off')),
    CONSTRAINT ck_invoices__amounts_non_negative CHECK (subtotal_amount >= 0 AND discount_amount >= 0 AND voucher_amount >= 0
                                                       AND tax_amount >= 0 AND total_amount >= 0 AND paid_amount >= 0),
    CONSTRAINT ck_invoices__due_after_issue CHECK (due_on IS NULL OR issued_on IS NULL OR due_on >= issued_on),
    CONSTRAINT ck_invoices__issued_when_not_draft CHECK (status = 'draft' OR issued_on IS NOT NULL)
);
CREATE INDEX ix_invoices__tenant_id__contact_id__issued_on ON billing.invoices (tenant_id, contact_id, issued_on DESC);
CREATE INDEX ix_invoices__billing_address_id ON billing.invoices (billing_address_id) WHERE billing_address_id IS NOT NULL;
CREATE INDEX ix_invoices__tenant_id__due_on__unpaid ON billing.invoices (tenant_id, due_on) WHERE status IN ('issued','partially_paid','overdue');
CREATE INDEX ix_invoices__tenant_id__created_at__id ON billing.invoices (tenant_id, created_at, id);
CREATE UNIQUE INDEX uq_invoices__legacy ON billing.invoices (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE billing.invoices IS 'A bill issued to one client for one or more order items, in one currency. One row = one invoice document (QuickBooks / VersaPay is the system of record for the printed invoice; external_ref links it). Owned by the billing module. Children: billing.invoice_lines; settled by billing.payment_allocations. Lifecycle: draft -> issued -> partially_paid/paid/overdue, or void/written_off; never deleted (financial history), a wrong invoice is voided. Contains PII (client billing identity through contact and address). [FINANCIAL]';
COMMENT ON COLUMN billing.invoices.id IS 'Surrogate key, system-generated (BY DEFAULT so the ETL can preserve ids if a source ever supplies them).';
COMMENT ON COLUMN billing.invoices.uuid IS 'Public identifier used in URLs and API payloads instead of the sequential id; system-generated.';
COMMENT ON COLUMN billing.invoices.tenant_id IS 'Owning tenant (core.tenants). Row-level security isolates invoices per tenant.';
COMMENT ON COLUMN billing.invoices.invoice_number IS 'Human invoice number printed on the document, unique within the tenant; system-generated from core.number_sequences or copied from QuickBooks for imported invoices. [FINANCIAL]';
COMMENT ON COLUMN billing.invoices.contact_id IS 'Billed client (crm.contacts): the doctor, scanning centre or DSO account that owes the money.';
COMMENT ON COLUMN billing.invoices.billing_address_id IS 'Billing address used on this invoice (crm.contact_addresses). NULL = no address selected; the client''s default billing address applies when rendering. [PII]';
COMMENT ON COLUMN billing.invoices.status IS 'Invoice lifecycle: ''draft'' = being prepared, not sent, editable; ''issued'' = sent to the client, amount owed; ''partially_paid'' = some payment allocated, balance > 0; ''paid'' = fully settled; ''overdue'' = issued, unpaid after due_on; ''void'' = cancelled, never owed; ''written_off'' = owed but abandoned as uncollectable.';
COMMENT ON COLUMN billing.invoices.currency_code IS 'Currency of every amount on this invoice and its lines (core.currencies). [FINANCIAL]';
COMMENT ON COLUMN billing.invoices.subtotal_amount IS 'Sum of line totals before invoice-level discount, vouchers and tax, in currency_code; calculated. [FINANCIAL]';
COMMENT ON COLUMN billing.invoices.discount_amount IS 'Invoice-level discount, in currency_code, non-negative; user input or calculated from pricing rules. [FINANCIAL]';
COMMENT ON COLUMN billing.invoices.voucher_amount IS 'Prepaid voucher credit applied to this invoice, in currency_code, non-negative; calculated from the vouchers ledger. [FINANCIAL]';
COMMENT ON COLUMN billing.invoices.tax_amount IS 'Sales tax / VAT on the invoice, in currency_code, non-negative; calculated. [FINANCIAL]';
COMMENT ON COLUMN billing.invoices.total_amount IS 'Amount owed by the client, in currency_code, non-negative; calculated by the billing functions (V100). TO CONFIRM: exact formula (subtotal - discount - voucher + tax) before a consistency CHECK is added. [FINANCIAL]';
COMMENT ON COLUMN billing.invoices.paid_amount IS 'Sum of payment allocations against this invoice, in currency_code, non-negative; calculated from billing.payment_allocations. [FINANCIAL]';
COMMENT ON COLUMN billing.invoices.balance_amount IS 'Outstanding amount = total_amount - paid_amount, in currency_code; generated column, negative only when the client overpaid. NULL = never (generated from two NOT NULL columns). [FINANCIAL]';
COMMENT ON COLUMN billing.invoices.issued_on IS 'Calendar date the invoice was issued to the client. NULL = still a draft (required once status is not draft).';
COMMENT ON COLUMN billing.invoices.due_on IS 'Calendar date payment is due (issue date + payment terms). NULL = no due date set (draft, or immediate payment).';
COMMENT ON COLUMN billing.invoices.paid_on IS 'Calendar date the invoice became fully paid. NULL = not fully paid.';
COMMENT ON COLUMN billing.invoices.external_ref IS 'QuickBooks / VersaPay document id, set by the integration layer. NULL = not yet synchronised to the accounting system.';
COMMENT ON COLUMN billing.invoices.notes IS 'Free-text note printed on or attached to the invoice; user input. May name a patient by mistake. NULL = no note. [PHI-RISK]';
COMMENT ON COLUMN billing.invoices.legacy_id IS 'Source row id of the legacy invoice record. NULL = created in threeddx3.';
COMMENT ON COLUMN billing.invoices.legacy_source IS 'Legacy table (or ec2:<path>) the row was migrated from. NULL = created in threeddx3.';
COMMENT ON COLUMN billing.invoices.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the source row, or created in threeddx3.';
COMMENT ON COLUMN billing.invoices.created_at IS 'UTC instant the row was created. [AUDIT]';
COMMENT ON COLUMN billing.invoices.updated_at IS 'UTC instant of the last change; maintained by trg_invoices__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN billing.invoices.created_by_user_id IS 'iam.users id of the person who created the row; no FK by design (history must survive user deletion). NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN billing.invoices.updated_by_user_id IS 'iam.users id of the last person to change the row; no FK by design. NULL = system or migration, or never updated. [AUDIT]';
COMMENT ON CONSTRAINT pk_invoices ON billing.invoices IS 'Each invoice is identified by its surrogate id.';
COMMENT ON CONSTRAINT uq_invoices__uuid ON billing.invoices IS 'The public uuid identifies exactly one invoice.';
COMMENT ON CONSTRAINT uq_invoices__tenant_id__invoice_number ON billing.invoices IS 'An invoice number is used once per tenant; accounting and clients refer to invoices by number.';
COMMENT ON CONSTRAINT ck_invoices__status ON billing.invoices IS 'Invoice status is one of the documented lifecycle values.';
COMMENT ON CONSTRAINT ck_invoices__amounts_non_negative ON billing.invoices IS 'Invoice amounts are never negative: credits to a client are reversing rows in billing.charges, not negative invoices.';
COMMENT ON CONSTRAINT ck_invoices__due_after_issue ON billing.invoices IS 'A due date cannot precede the issue date.';
COMMENT ON CONSTRAINT ck_invoices__issued_when_not_draft ON billing.invoices IS 'Every non-draft invoice has an issue date.';
COMMENT ON INDEX billing.ix_invoices__tenant_id__contact_id__issued_on IS 'Client statement: invoices of one client, newest first; also covers the contact_id FK.';
COMMENT ON INDEX billing.ix_invoices__billing_address_id IS 'Covers the billing_address_id FK (address deletion check).';
COMMENT ON INDEX billing.ix_invoices__tenant_id__due_on__unpaid IS 'Receivables / dunning list: open invoices by due date.';
COMMENT ON INDEX billing.ix_invoices__tenant_id__created_at__id IS 'Stable keyset pagination of invoices per tenant.';
COMMENT ON INDEX billing.uq_invoices__legacy IS 'Every migrated invoice is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_invoices__touch_updated_at BEFORE UPDATE ON billing.invoices
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_invoices__touch_updated_at ON billing.invoices IS 'Sets updated_at and updated_by_user_id on every update.';

-- ---------------------------------------------------------------- charges (append-only)
CREATE TABLE billing.charges (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    uuid                uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    contact_id          bigint NOT NULL,
    order_id            bigint,
    order_item_id       bigint,
    invoice_id          bigint,
    charge_kind         varchar(30) NOT NULL DEFAULT 'service',
    reverses_charge_id  bigint,
    currency_code       core.currency_code NOT NULL,
    amount              core.money_amount NOT NULL,
    charged_on          date NOT NULL DEFAULT CURRENT_DATE,
    is_manual           boolean NOT NULL DEFAULT false,
    reason              varchar(255),
    actor_user_id       bigint,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    CONSTRAINT pk_charges PRIMARY KEY (id),
    CONSTRAINT uq_charges__uuid UNIQUE (uuid),
    CONSTRAINT fk_charges__invoice_id FOREIGN KEY (invoice_id) REFERENCES billing.invoices (id) ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_charges__reverses_charge_id FOREIGN KEY (reverses_charge_id) REFERENCES billing.charges (id) ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT ck_charges__charge_kind CHECK (charge_kind IN ('service','product','shipping','rush','adjustment','credit','refund')),
    CONSTRAINT ck_charges__amount_sign CHECK (
        (charge_kind IN ('service','product','shipping','rush') AND amount >= 0)
     OR (charge_kind IN ('credit','refund') AND amount < 0)
     OR (charge_kind = 'adjustment' AND amount <> 0)),
    CONSTRAINT ck_charges__reversal_kind CHECK (reverses_charge_id IS NULL OR charge_kind IN ('credit','refund')),
    CONSTRAINT ck_charges__not_self_reversal CHECK (reverses_charge_id IS NULL OR reverses_charge_id <> id)
);
CREATE INDEX ix_charges__tenant_id__contact_id__charged_on ON billing.charges (tenant_id, contact_id, charged_on DESC);
CREATE INDEX ix_charges__tenant_id__charged_on__charge_kind ON billing.charges (tenant_id, charged_on DESC, charge_kind);
CREATE INDEX ix_charges__tenant_id__order_id ON billing.charges (tenant_id, order_id) WHERE order_id IS NOT NULL;
CREATE INDEX ix_charges__tenant_id__order_item_id ON billing.charges (tenant_id, order_item_id) WHERE order_item_id IS NOT NULL;
CREATE INDEX ix_charges__invoice_id ON billing.charges (invoice_id) WHERE invoice_id IS NOT NULL;
CREATE INDEX ix_charges__reverses_charge_id ON billing.charges (reverses_charge_id) WHERE reverses_charge_id IS NOT NULL;
CREATE INDEX ix_charges__tenant_id__created_at__id ON billing.charges (tenant_id, created_at, id);
CREATE UNIQUE INDEX uq_charges__legacy ON billing.charges (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE billing.charges IS 'Append-only charge ledger: one row per chargeable event (an order item charged, a shipping or rush fee, a manual adjustment) or per reversal of one. Answers "what were total charges yesterday?" without touching orders; the net charge of an order item is SUM(amount) over its rows. A row''s existence is the charged state (there is no status column). Uncharge (CP restOrder/uncharge, voucher/uncharge, unchargeIsmileSubOrder; D4 rule 6) inserts a reversing row with charge_kind credit/refund, a negative amount and reverses_charge_id pointing at the original; rows are never updated or deleted (trg_charges__append_only). Owned by the billing module. [FINANCIAL]';
COMMENT ON COLUMN billing.charges.id IS 'Surrogate key, system-generated.';
COMMENT ON COLUMN billing.charges.uuid IS 'Public identifier of the charge for APIs and accounting exports; system-generated.';
COMMENT ON COLUMN billing.charges.tenant_id IS 'Owning tenant (core.tenants).';
COMMENT ON COLUMN billing.charges.contact_id IS 'Client charged (crm.contacts). For a reversal it is the same client as the original charge.';
COMMENT ON COLUMN billing.charges.order_id IS 'Order the charge belongs to (orders.orders). NULL = a charge not tied to an order (annual fee, account-level adjustment).';
COMMENT ON COLUMN billing.charges.order_item_id IS 'Order item charged (orders.order_items). NULL = order-level or account-level charge (shipping, rush, adjustment).';
COMMENT ON COLUMN billing.charges.invoice_id IS 'Invoice the charge was billed on, when known at insert time (billing.invoices). The row is append-only, so a charge invoiced later is linked through billing.invoice_lines.charge_id instead. NULL = not invoiced when recorded.';
COMMENT ON COLUMN billing.charges.charge_kind IS 'What was charged: ''service'' = design/planning/production service on an order item; ''product'' = physical good or licence; ''shipping'' = shipping fee; ''rush'' = rush (expedite) fee; ''adjustment'' = manual correction, either sign; ''credit'' = reversal or goodwill credit to the client (negative); ''refund'' = reversal of a charge whose money was returned (negative).';
COMMENT ON COLUMN billing.charges.reverses_charge_id IS 'The original charge this row reverses (uncharge). Only credit/refund rows may carry it; partial reversals are allowed, so several rows may reverse one charge. NULL = not a reversal (an original charge, or a credit not tied to one charge).';
COMMENT ON COLUMN billing.charges.currency_code IS 'Currency of amount (core.currencies). [FINANCIAL]';
COMMENT ON COLUMN billing.charges.amount IS 'Signed amount in currency_code: >= 0 for service/product/shipping/rush (0 only for a zero-charge item with a zero-charge reason on the order item), < 0 for credit/refund, non-zero either sign for adjustment. SUM(amount) is the net charge. [FINANCIAL]';
COMMENT ON COLUMN billing.charges.charged_on IS 'Business date of the charge (the day the item was charged), used for daily charge reports; defaults to today.';
COMMENT ON COLUMN billing.charges.is_manual IS 'true = entered by a staff member by hand; false = written by the charging process when an order item reached its charge point.';
COMMENT ON COLUMN billing.charges.reason IS 'Why the charge or reversal was made (required in practice for manual rows and uncharges; enforced by V100). User input; may name a patient by mistake. NULL = automatic charge with no reason needed. [PHI-RISK]';
COMMENT ON COLUMN billing.charges.actor_user_id IS 'iam.users id of the staff member who charged or uncharged. No FK: actor history must survive user deletion and the table is append-only, so an ON DELETE SET NULL could never run. NULL = charged by the system or migration. [AUDIT]';
COMMENT ON COLUMN billing.charges.legacy_id IS 'Source row id of the legacy charge (e.g. CreateOrderCharge). NULL = created in threeddx3.';
COMMENT ON COLUMN billing.charges.legacy_source IS 'Legacy table the row was migrated from. NULL = created in threeddx3.';
COMMENT ON COLUMN billing.charges.legacy_key IS 'Composite legacy key when one id is not enough (e.g. order + service). NULL = legacy_id suffices, or created in threeddx3.';
COMMENT ON COLUMN billing.charges.created_at IS 'UTC instant the charge row was recorded. [AUDIT]';
COMMENT ON COLUMN billing.charges.created_by_user_id IS 'iam.users id of the session user that inserted the row; no FK by design. NULL = system or migration. [AUDIT]';
COMMENT ON CONSTRAINT pk_charges ON billing.charges IS 'Each charge row is identified by its surrogate id.';
COMMENT ON CONSTRAINT uq_charges__uuid ON billing.charges IS 'The public uuid identifies exactly one charge.';
COMMENT ON CONSTRAINT fk_charges__invoice_id ON billing.charges IS 'A charge billed on an invoice keeps that invoice: invoices with charges cannot be deleted (void them instead).';
COMMENT ON CONSTRAINT fk_charges__reverses_charge_id ON billing.charges IS 'A reversal points at the charge it reverses; an original charge with reversals cannot be deleted (and no charge can be, the ledger is append-only).';
COMMENT ON CONSTRAINT ck_charges__charge_kind ON billing.charges IS 'Charge kind is one of the documented values.';
COMMENT ON CONSTRAINT ck_charges__amount_sign ON billing.charges IS 'Amounts are signed by kind: debits are >= 0, credits and refunds are negative, adjustments are non-zero; so SUM(amount) is always the net amount owed.';
COMMENT ON CONSTRAINT ck_charges__reversal_kind ON billing.charges IS 'Only a credit or refund row can reverse another charge (uncharge = reversing entry, D4 rule 6).';
COMMENT ON CONSTRAINT ck_charges__not_self_reversal ON billing.charges IS 'A charge cannot reverse itself.';
COMMENT ON INDEX billing.ix_charges__tenant_id__contact_id__charged_on IS 'Client account history: charges of one client by date; covers the contact_id FK.';
COMMENT ON INDEX billing.ix_charges__tenant_id__charged_on__charge_kind IS 'Daily charge reports ("total charges yesterday" by kind).';
COMMENT ON INDEX billing.ix_charges__tenant_id__order_id IS 'Charges of one order (charged / not-charged screens); covers the order_id FK.';
COMMENT ON INDEX billing.ix_charges__tenant_id__order_item_id IS 'Net charge of one order item (charge + reversals); covers the order_item_id FK.';
COMMENT ON INDEX billing.ix_charges__invoice_id IS 'Charges billed on one invoice; covers the invoice_id FK.';
COMMENT ON INDEX billing.ix_charges__reverses_charge_id IS 'Reversals of one charge (how much of it is still charged); covers the self FK.';
COMMENT ON INDEX billing.ix_charges__tenant_id__created_at__id IS 'Stable keyset pagination of the charge ledger per tenant.';
COMMENT ON INDEX billing.uq_charges__legacy IS 'Every migrated charge is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_charges__append_only BEFORE UPDATE OR DELETE ON billing.charges
    FOR EACH ROW EXECUTE FUNCTION core.fn_reject_mutation();
COMMENT ON TRIGGER trg_charges__append_only ON billing.charges IS 'Rejects every UPDATE and DELETE: the charge ledger is append-only; an uncharge is a new credit/refund row with reverses_charge_id.';

-- ---------------------------------------------------------------- invoice lines
CREATE TABLE billing.invoice_lines (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    invoice_id          bigint NOT NULL,
    order_id            bigint,
    order_item_id       bigint,
    charge_id           bigint,
    line_number         smallint NOT NULL DEFAULT 1,
    description         varchar(255) NOT NULL,
    quantity            numeric(10,3) NOT NULL DEFAULT 1,
    unit_amount         core.money_amount NOT NULL DEFAULT 0,
    discount_amount     core.money_amount NOT NULL DEFAULT 0,
    tax_percent         core.rate_percent NOT NULL DEFAULT 0,
    line_total          core.money_amount NOT NULL DEFAULT 0,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_invoice_lines PRIMARY KEY (id),
    CONSTRAINT uq_invoice_lines__invoice_id__line_number UNIQUE (invoice_id, line_number),
    CONSTRAINT fk_invoice_lines__invoice_id FOREIGN KEY (invoice_id) REFERENCES billing.invoices (id) ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_invoice_lines__charge_id FOREIGN KEY (charge_id) REFERENCES billing.charges (id) ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT ck_invoice_lines__line_number_positive CHECK (line_number >= 1),
    CONSTRAINT ck_invoice_lines__quantity_positive CHECK (quantity > 0),
    CONSTRAINT ck_invoice_lines__amounts_non_negative CHECK (unit_amount >= 0 AND discount_amount >= 0 AND line_total >= 0)
);
CREATE INDEX ix_invoice_lines__tenant_id__order_id ON billing.invoice_lines (tenant_id, order_id) WHERE order_id IS NOT NULL;
CREATE INDEX ix_invoice_lines__tenant_id__order_item_id ON billing.invoice_lines (tenant_id, order_item_id) WHERE order_item_id IS NOT NULL;
CREATE INDEX ix_invoice_lines__charge_id ON billing.invoice_lines (charge_id) WHERE charge_id IS NOT NULL;
CREATE UNIQUE INDEX uq_invoice_lines__legacy ON billing.invoice_lines (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE billing.invoice_lines IS 'One billed line on an invoice: usually one order item or one charge, with quantity, unit price, discount and tax. Child of billing.invoices; amounts are in the invoice''s currency_code. Editable while the invoice is a draft; frozen once issued (financial edit lock, V100). Never deleted once the invoice exists (RESTRICT). [FINANCIAL]';
COMMENT ON COLUMN billing.invoice_lines.id IS 'Surrogate key, system-generated.';
COMMENT ON COLUMN billing.invoice_lines.tenant_id IS 'Owning tenant; defaults to the session tenant (core.fn_current_tenant()) so writers that only know the invoice still fill it, and must equal the invoice''s tenant.';
COMMENT ON COLUMN billing.invoice_lines.invoice_id IS 'Invoice this line belongs to (billing.invoices).';
COMMENT ON COLUMN billing.invoice_lines.order_id IS 'Order billed by this line (orders.orders). NULL = line not tied to an order (fee, manual line).';
COMMENT ON COLUMN billing.invoice_lines.order_item_id IS 'Order item billed by this line (orders.order_items). NULL = order-level or manual line.';
COMMENT ON COLUMN billing.invoice_lines.charge_id IS 'Charge row this line bills (billing.charges); links a charge invoiced after it was recorded, since charges are append-only. NULL = line not derived from a charge row (manual or migrated line).';
COMMENT ON COLUMN billing.invoice_lines.line_number IS 'Position of the line on the printed invoice, 1-based, unique per invoice.';
COMMENT ON COLUMN billing.invoice_lines.description IS 'Line text printed on the invoice (service name, order reference); user input or generated. May contain a patient reference copied from the order. [SNAPSHOT] [PHI-RISK]';
COMMENT ON COLUMN billing.invoice_lines.quantity IS 'Units billed (arches, implants, hours, pieces), > 0, three decimals.';
COMMENT ON COLUMN billing.invoice_lines.unit_amount IS 'Price per unit in the invoice currency, non-negative; copied from the order item price at invoicing. [SNAPSHOT] [FINANCIAL]';
COMMENT ON COLUMN billing.invoice_lines.discount_amount IS 'Discount on this line in the invoice currency, non-negative. [FINANCIAL]';
COMMENT ON COLUMN billing.invoice_lines.tax_percent IS 'Tax rate applied to this line, percent 0-100.';
COMMENT ON COLUMN billing.invoice_lines.line_total IS 'Line amount after discount (and tax where the tenant invoices tax per line), invoice currency, non-negative; calculated. Credits are reversing charges, not negative lines. [FINANCIAL]';
COMMENT ON COLUMN billing.invoice_lines.legacy_id IS 'Source row id of the legacy invoice line. NULL = created in threeddx3.';
COMMENT ON COLUMN billing.invoice_lines.legacy_source IS 'Legacy table the row was migrated from. NULL = created in threeddx3.';
COMMENT ON COLUMN billing.invoice_lines.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id suffices, or created in threeddx3.';
COMMENT ON COLUMN billing.invoice_lines.created_at IS 'UTC instant the line was created. [AUDIT]';
COMMENT ON COLUMN billing.invoice_lines.updated_at IS 'UTC instant of the last change; maintained by trg_invoice_lines__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN billing.invoice_lines.created_by_user_id IS 'iam.users id of the creator; no FK by design. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN billing.invoice_lines.updated_by_user_id IS 'iam.users id of the last editor; no FK by design. NULL = system, migration, or never updated. [AUDIT]';
COMMENT ON CONSTRAINT pk_invoice_lines ON billing.invoice_lines IS 'Each invoice line is identified by its surrogate id.';
COMMENT ON CONSTRAINT uq_invoice_lines__invoice_id__line_number ON billing.invoice_lines IS 'Line numbers are unique within an invoice; also serves invoice -> lines lookups and the invoice_id FK.';
COMMENT ON CONSTRAINT fk_invoice_lines__invoice_id ON billing.invoice_lines IS 'A line belongs to one invoice; an invoice with lines cannot be deleted (financial history: void it).';
COMMENT ON CONSTRAINT fk_invoice_lines__charge_id ON billing.invoice_lines IS 'A line may bill one charge row; the charge cannot disappear while invoiced (charges are append-only anyway).';
COMMENT ON CONSTRAINT ck_invoice_lines__line_number_positive ON billing.invoice_lines IS 'Line numbers start at 1.';
COMMENT ON CONSTRAINT ck_invoice_lines__quantity_positive ON billing.invoice_lines IS 'A billed quantity is strictly positive.';
COMMENT ON CONSTRAINT ck_invoice_lines__amounts_non_negative ON billing.invoice_lines IS 'Unit price, discount and line total are never negative; credits are reversing charges.';
COMMENT ON INDEX billing.ix_invoice_lines__tenant_id__order_id IS 'Invoice lines of one order; covers the order_id FK.';
COMMENT ON INDEX billing.ix_invoice_lines__tenant_id__order_item_id IS 'Is this order item invoiced, and on which invoice; covers the order_item_id FK.';
COMMENT ON INDEX billing.ix_invoice_lines__charge_id IS 'Which invoice line billed a charge; covers the charge_id FK.';
COMMENT ON INDEX billing.uq_invoice_lines__legacy IS 'Every migrated invoice line is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_invoice_lines__touch_updated_at BEFORE UPDATE ON billing.invoice_lines
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_invoice_lines__touch_updated_at ON billing.invoice_lines IS 'Sets updated_at and updated_by_user_id on every update.';

-- ---------------------------------------------------------------- payment methods
CREATE TABLE billing.payment_methods (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    uuid                uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    contact_id          bigint NOT NULL,
    method_kind         varchar(30) NOT NULL,
    display_label       varchar(120),
    processor_code      varchar(40),
    provider_token      varchar(255),
    card_brand          varchar(20),
    last4               char(4),
    expiry_month        smallint,
    expiry_year         smallint,
    expires_on          date,
    is_default          boolean NOT NULL DEFAULT false,
    is_active           boolean NOT NULL DEFAULT true,
    deactivated_at      timestamptz,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_payment_methods PRIMARY KEY (id),
    CONSTRAINT uq_payment_methods__uuid UNIQUE (uuid),
    CONSTRAINT ck_payment_methods__method_kind CHECK (method_kind IN ('card','bank_transfer','cheque','cash','credit_balance','third_party')),
    CONSTRAINT ck_payment_methods__processor_code CHECK (processor_code IS NULL OR processor_code IN ('versapay','cybersource','skyline','quickbooks','other')),
    CONSTRAINT ck_payment_methods__card_brand CHECK (card_brand IS NULL OR card_brand IN ('visa','mastercard','amex')),
    CONSTRAINT ck_payment_methods__last4_digits CHECK (last4 IS NULL OR last4 ~ '^[0-9]{4}$'),
    CONSTRAINT ck_payment_methods__expiry_month_range CHECK (expiry_month IS NULL OR expiry_month BETWEEN 1 AND 12),
    CONSTRAINT ck_payment_methods__expiry_year_range CHECK (expiry_year IS NULL OR expiry_year BETWEEN 2000 AND 2100),
    CONSTRAINT ck_payment_methods__expiry_pair CHECK ((expiry_month IS NULL) = (expiry_year IS NULL)),
    CONSTRAINT ck_payment_methods__card_fields_only_for_cards CHECK (method_kind = 'card' OR num_nonnulls(card_brand, last4, expiry_month, expiry_year) = 0),
    CONSTRAINT ck_payment_methods__default_is_active CHECK (NOT is_default OR is_active)
);
CREATE UNIQUE INDEX uq_payment_methods__contact_id__default_active ON billing.payment_methods (contact_id)
    WHERE is_default AND is_active;
CREATE INDEX ix_payment_methods__tenant_id__contact_id ON billing.payment_methods (tenant_id, contact_id);
CREATE UNIQUE INDEX uq_payment_methods__legacy ON billing.payment_methods (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE billing.payment_methods IS 'A client''s stored way to pay: a tokenised card, bank transfer, cheque, cash, credit balance or third-party payer. Cards are held only as a gateway vault/processor token reference plus brand, last four digits and expiry for recognition: the card number (PAN) and CVV are NEVER stored in this database (out of PCI scope; legacy UserAcounts.CreditCard is deliberately not migrated). At most one default active method per client (iSmileOn payment method requirement). Lifecycle: deactivated (is_active=false), never deleted while payments reference it. Contains PII. [FINANCIAL]';
COMMENT ON COLUMN billing.payment_methods.id IS 'Surrogate key, system-generated.';
COMMENT ON COLUMN billing.payment_methods.uuid IS 'Public identifier of the payment method for the portals and APIs; system-generated.';
COMMENT ON COLUMN billing.payment_methods.tenant_id IS 'Owning tenant (core.tenants).';
COMMENT ON COLUMN billing.payment_methods.contact_id IS 'Client who owns the payment method (crm.contacts); migrated from UserAcounts.uID.';
COMMENT ON COLUMN billing.payment_methods.method_kind IS 'Kind of method: ''card'' = tokenised payment card; ''bank_transfer'' = wire/ACH; ''cheque'' = paper cheque; ''cash'' = cash; ''credit_balance'' = paid from the client''s account credit; ''third_party'' = paid by another party (DSO, financing).';
COMMENT ON COLUMN billing.payment_methods.display_label IS 'Masked label shown to users, e.g. "VISA ****1019"; never contains more than the last four digits. Migrated from UserAcounts.CardType + last four. NULL = no label (method recognised by kind only).';
COMMENT ON COLUMN billing.payment_methods.processor_code IS 'Payment gateway holding the vault token: ''versapay'', ''cybersource'', ''skyline'', ''quickbooks'', ''other''. Migrated from the UserAcounts vault column that was filled (VersaPayVaultID, CybersourceBillRekID/BillRek, SkyLineVaultID). NULL = no gateway (non-card method or card without token).';
COMMENT ON COLUMN billing.payment_methods.provider_token IS 'Opaque vault/processor token reference issued by the gateway (processor_code) and used to charge the card. It is NOT a card number: no PAN, CVV or bank account number is ever stored in this database. NULL = no token on file (method cannot be charged automatically). [SECRET-REF] [PII]';
COMMENT ON COLUMN billing.payment_methods.card_brand IS 'Card network: ''visa'', ''mastercard'', ''amex'' (the brands the portals accept; legacy CardType 1/3/2). "Not Specified" in the portal means no active row, not a value. NULL = not a card, or brand unknown for a migrated card.';
COMMENT ON COLUMN billing.payment_methods.last4 IS 'Last four digits of the card number, exactly four digits, for display and recognition only. NULL = not a card, or not known (legacy ciphertext rows). [PII]';
COMMENT ON COLUMN billing.payment_methods.expiry_month IS 'Card expiry month 1-12. NULL = not a card or expiry unknown (set together with expiry_year).';
COMMENT ON COLUMN billing.payment_methods.expiry_year IS 'Card expiry year, four digits (2000-2100). NULL = not a card or expiry unknown (set together with expiry_month).';
COMMENT ON COLUMN billing.payment_methods.expires_on IS 'Last calendar day the method is valid (end of the expiry month for cards); written by the ETL from UserAcounts.ExpireDate and kept for queries such as "cards expiring this month". NULL = no expiry known or not applicable.';
COMMENT ON COLUMN billing.payment_methods.is_default IS 'true = the method charged when the client does not choose one; at most one default active method per client (uq_payment_methods__contact_id__default_active).';
COMMENT ON COLUMN billing.payment_methods.is_active IS 'true = usable for new payments; false = deactivated by the client or staff (kept for payment history).';
COMMENT ON COLUMN billing.payment_methods.deactivated_at IS 'UTC instant the method was deactivated. NULL = active, or deactivated before threeddx3 (migrated, date unknown).';
COMMENT ON COLUMN billing.payment_methods.legacy_id IS 'Source row id (UserAcounts.uID for migrated cards). NULL = created in threeddx3.';
COMMENT ON COLUMN billing.payment_methods.legacy_source IS 'Legacy table the row was migrated from (UserAcounts). NULL = created in threeddx3.';
COMMENT ON COLUMN billing.payment_methods.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id suffices, or created in threeddx3.';
COMMENT ON COLUMN billing.payment_methods.created_at IS 'UTC instant the method was stored. [AUDIT]';
COMMENT ON COLUMN billing.payment_methods.updated_at IS 'UTC instant of the last change; maintained by trg_payment_methods__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN billing.payment_methods.created_by_user_id IS 'iam.users id of the creator; no FK by design. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN billing.payment_methods.updated_by_user_id IS 'iam.users id of the last editor; no FK by design. NULL = system, migration, or never updated. [AUDIT]';
COMMENT ON CONSTRAINT pk_payment_methods ON billing.payment_methods IS 'Each payment method is identified by its surrogate id.';
COMMENT ON CONSTRAINT uq_payment_methods__uuid ON billing.payment_methods IS 'The public uuid identifies exactly one payment method.';
COMMENT ON CONSTRAINT ck_payment_methods__method_kind ON billing.payment_methods IS 'Method kind is one of the documented values.';
COMMENT ON CONSTRAINT ck_payment_methods__processor_code ON billing.payment_methods IS 'Gateway code is one of the gateways 3DDX has used (legacy ChargingSystem values) or ''other''.';
COMMENT ON CONSTRAINT ck_payment_methods__card_brand ON billing.payment_methods IS 'Accepted card brands are Visa, Mastercard and American Express (iSmileOn payment method spec; legacy CardType map).';
COMMENT ON CONSTRAINT ck_payment_methods__last4_digits ON billing.payment_methods IS 'last4 holds exactly four digits, so a full card number can never be stored there.';
COMMENT ON CONSTRAINT ck_payment_methods__expiry_month_range ON billing.payment_methods IS 'Expiry month is 1-12.';
COMMENT ON CONSTRAINT ck_payment_methods__expiry_year_range ON billing.payment_methods IS 'Expiry year is a four-digit year 2000-2100 (two-digit years are expanded at the edge).';
COMMENT ON CONSTRAINT ck_payment_methods__expiry_pair ON billing.payment_methods IS 'Expiry month and year are recorded together or not at all.';
COMMENT ON CONSTRAINT ck_payment_methods__card_fields_only_for_cards ON billing.payment_methods IS 'Brand, last four and expiry exist only on card methods.';
COMMENT ON CONSTRAINT ck_payment_methods__default_is_active ON billing.payment_methods IS 'A deactivated method cannot be the client''s default.';
COMMENT ON INDEX billing.uq_payment_methods__contact_id__default_active IS 'Business rule: a client has at most one default active payment method.';
COMMENT ON INDEX billing.ix_payment_methods__tenant_id__contact_id IS 'Payment methods of one client (profile screen, charging); covers the contact_id FK.';
COMMENT ON INDEX billing.uq_payment_methods__legacy IS 'Every migrated payment method is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_payment_methods__touch_updated_at BEFORE UPDATE ON billing.payment_methods
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_payment_methods__touch_updated_at ON billing.payment_methods IS 'Sets updated_at and updated_by_user_id on every update.';

-- ---------------------------------------------------------------- payments
CREATE TABLE billing.payments (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    uuid                uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    contact_id          bigint NOT NULL,
    payment_method_id   bigint,
    currency_code       core.currency_code NOT NULL,
    amount              core.money_amount NOT NULL,
    status              varchar(20) NOT NULL DEFAULT 'pending',
    received_on         date,
    external_ref        varchar(120),
    failure_reason      varchar(255),
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_payments PRIMARY KEY (id),
    CONSTRAINT uq_payments__uuid UNIQUE (uuid),
    CONSTRAINT fk_payments__payment_method_id FOREIGN KEY (payment_method_id) REFERENCES billing.payment_methods (id) ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT ck_payments__amount_non_zero CHECK (amount <> 0),
    CONSTRAINT ck_payments__status CHECK (status IN ('pending','authorised','captured','failed','refunded','cancelled')),
    CONSTRAINT ck_payments__failure_reason_when_failed CHECK (status = 'failed' OR failure_reason IS NULL)
);
CREATE INDEX ix_payments__tenant_id__contact_id__received_on ON billing.payments (tenant_id, contact_id, received_on DESC);
CREATE INDEX ix_payments__payment_method_id ON billing.payments (payment_method_id) WHERE payment_method_id IS NOT NULL;
CREATE INDEX ix_payments__tenant_id__created_at__id ON billing.payments (tenant_id, created_at, id);
CREATE UNIQUE INDEX uq_payments__legacy ON billing.payments (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE billing.payments IS 'Money received from (or returned to) a client through the gateway, bank or by hand. One row = one payment transaction; applied to invoices through billing.payment_allocations. Lifecycle: pending -> authorised -> captured, or failed/cancelled; refunded when returned. Never deleted (financial history). Contains PII. [FINANCIAL]';
COMMENT ON COLUMN billing.payments.id IS 'Surrogate key, system-generated.';
COMMENT ON COLUMN billing.payments.uuid IS 'Public identifier of the payment; system-generated.';
COMMENT ON COLUMN billing.payments.tenant_id IS 'Owning tenant (core.tenants).';
COMMENT ON COLUMN billing.payments.contact_id IS 'Client who paid (crm.contacts).';
COMMENT ON COLUMN billing.payments.payment_method_id IS 'Stored method used (billing.payment_methods). NULL = one-off payment with no stored method (cash, cheque, wire not on file).';
COMMENT ON COLUMN billing.payments.currency_code IS 'Currency of amount (core.currencies). [FINANCIAL]';
COMMENT ON COLUMN billing.payments.amount IS 'Payment amount in currency_code: positive = money received, negative = money returned to the client; never zero. [FINANCIAL]';
COMMENT ON COLUMN billing.payments.status IS 'Payment state: ''pending'' = initiated, not yet confirmed; ''authorised'' = gateway authorised, not captured; ''captured'' = money received; ''failed'' = declined or errored (see failure_reason); ''refunded'' = captured then returned; ''cancelled'' = abandoned before capture.';
COMMENT ON COLUMN billing.payments.received_on IS 'Calendar date the money was received (captured). NULL = not yet received.';
COMMENT ON COLUMN billing.payments.external_ref IS 'Gateway or accounting transaction id (CyberSource, VersaPay, QuickBooks). NULL = no external reference (manual cash/cheque entry).';
COMMENT ON COLUMN billing.payments.failure_reason IS 'Gateway decline or error text; only on failed payments. NULL = payment did not fail.';
COMMENT ON COLUMN billing.payments.legacy_id IS 'Source row id of the legacy payment. NULL = created in threeddx3.';
COMMENT ON COLUMN billing.payments.legacy_source IS 'Legacy table the row was migrated from. NULL = created in threeddx3.';
COMMENT ON COLUMN billing.payments.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id suffices, or created in threeddx3.';
COMMENT ON COLUMN billing.payments.created_at IS 'UTC instant the payment row was created. [AUDIT]';
COMMENT ON COLUMN billing.payments.updated_at IS 'UTC instant of the last change; maintained by trg_payments__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN billing.payments.created_by_user_id IS 'iam.users id of the creator; no FK by design. NULL = system, gateway webhook or migration. [AUDIT]';
COMMENT ON COLUMN billing.payments.updated_by_user_id IS 'iam.users id of the last editor; no FK by design. NULL = system, migration, or never updated. [AUDIT]';
COMMENT ON CONSTRAINT pk_payments ON billing.payments IS 'Each payment is identified by its surrogate id.';
COMMENT ON CONSTRAINT uq_payments__uuid ON billing.payments IS 'The public uuid identifies exactly one payment.';
COMMENT ON CONSTRAINT fk_payments__payment_method_id ON billing.payments IS 'A payment keeps the method it was made with; a method with payments is deactivated, never deleted.';
COMMENT ON CONSTRAINT ck_payments__amount_non_zero ON billing.payments IS 'A payment moves money: zero-amount payments are not recorded.';
COMMENT ON CONSTRAINT ck_payments__status ON billing.payments IS 'Payment status is one of the documented values.';
COMMENT ON CONSTRAINT ck_payments__failure_reason_when_failed ON billing.payments IS 'A failure reason is recorded only on failed payments.';
COMMENT ON INDEX billing.ix_payments__tenant_id__contact_id__received_on IS 'Payment history of one client, newest first; covers the contact_id FK.';
COMMENT ON INDEX billing.ix_payments__payment_method_id IS 'Payments made with one method (deactivation check); covers the payment_method_id FK.';
COMMENT ON INDEX billing.ix_payments__tenant_id__created_at__id IS 'Stable keyset pagination of payments per tenant.';
COMMENT ON INDEX billing.uq_payments__legacy IS 'Every migrated payment is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_payments__touch_updated_at BEFORE UPDATE ON billing.payments
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_payments__touch_updated_at ON billing.payments IS 'Sets updated_at and updated_by_user_id on every update.';

-- ---------------------------------------------------------------- payment allocations
CREATE TABLE billing.payment_allocations (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    payment_id          bigint NOT NULL,
    invoice_id          bigint NOT NULL,
    amount              core.money_amount NOT NULL,
    allocated_at        timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    CONSTRAINT pk_payment_allocations PRIMARY KEY (id),
    CONSTRAINT uq_payment_allocations__payment_id__invoice_id UNIQUE (payment_id, invoice_id),
    CONSTRAINT fk_payment_allocations__payment_id FOREIGN KEY (payment_id) REFERENCES billing.payments (id) ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_payment_allocations__invoice_id FOREIGN KEY (invoice_id) REFERENCES billing.invoices (id) ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT ck_payment_allocations__amount_positive CHECK (amount > 0)
);
CREATE INDEX ix_payment_allocations__invoice_id ON billing.payment_allocations (invoice_id);

COMMENT ON TABLE billing.payment_allocations IS 'How much of one payment settles one invoice (many-to-many: one payment may pay several invoices, one invoice may be paid in instalments). Amounts are in the payment''s and invoice''s common currency. Drives billing.invoices.paid_amount (V100). Financial history: rows are not deleted while either side exists (RESTRICT); a wrong allocation is reversed by the billing functions. [FINANCIAL]';
COMMENT ON COLUMN billing.payment_allocations.id IS 'Surrogate key, system-generated.';
COMMENT ON COLUMN billing.payment_allocations.tenant_id IS 'Owning tenant; defaults to the session tenant (core.fn_current_tenant()) and must equal the payment''s tenant.';
COMMENT ON COLUMN billing.payment_allocations.payment_id IS 'Payment being applied (billing.payments).';
COMMENT ON COLUMN billing.payment_allocations.invoice_id IS 'Invoice being settled (billing.invoices).';
COMMENT ON COLUMN billing.payment_allocations.amount IS 'Amount of the payment applied to the invoice, strictly positive, in the invoice currency. [FINANCIAL]';
COMMENT ON COLUMN billing.payment_allocations.allocated_at IS 'UTC instant the allocation was made. [AUDIT]';
COMMENT ON COLUMN billing.payment_allocations.created_by_user_id IS 'iam.users id of the person who allocated; no FK by design. NULL = automatic allocation or migration. [AUDIT]';
COMMENT ON CONSTRAINT pk_payment_allocations ON billing.payment_allocations IS 'Each allocation is identified by its surrogate id.';
COMMENT ON CONSTRAINT uq_payment_allocations__payment_id__invoice_id ON billing.payment_allocations IS 'One allocation row per (payment, invoice); a further amount updates it. Also covers the payment_id FK.';
COMMENT ON CONSTRAINT fk_payment_allocations__payment_id ON billing.payment_allocations IS 'An allocated payment cannot be deleted (financial history).';
COMMENT ON CONSTRAINT fk_payment_allocations__invoice_id ON billing.payment_allocations IS 'An invoice with allocated payments cannot be deleted (financial history).';
COMMENT ON CONSTRAINT ck_payment_allocations__amount_positive ON billing.payment_allocations IS 'An allocation applies a strictly positive amount.';
COMMENT ON INDEX billing.ix_payment_allocations__invoice_id IS 'Payments applied to one invoice (paid_amount recalculation); covers the invoice_id FK.';

-- ---------------------------------------------------------------- annual payments
CREATE TABLE billing.annual_payments (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    contact_id          bigint NOT NULL,
    fiscal_year         smallint NOT NULL,
    currency_code       core.currency_code NOT NULL,
    committed_amount    core.money_amount NOT NULL DEFAULT 0,
    paid_amount         core.money_amount NOT NULL DEFAULT 0,
    notes               text,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_annual_payments PRIMARY KEY (id),
    CONSTRAINT uq_annual_payments__contact_id__fiscal_year UNIQUE (contact_id, fiscal_year),
    CONSTRAINT ck_annual_payments__fiscal_year_range CHECK (fiscal_year BETWEEN 2000 AND 2100),
    CONSTRAINT ck_annual_payments__amounts_non_negative CHECK (committed_amount >= 0 AND paid_amount >= 0)
);
CREATE INDEX ix_annual_payments__tenant_id__fiscal_year ON billing.annual_payments (tenant_id, fiscal_year);
CREATE UNIQUE INDEX uq_annual_payments__legacy ON billing.annual_payments (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE billing.annual_payments IS 'Per client per fiscal year: the yearly commitment (prepaid package) and what was actually paid. Migrated from legacy annualPayments (uID, payments, year), which records only the paid figure. One row per (client, year). Edited by finance; not deleted. [FINANCIAL]';
COMMENT ON COLUMN billing.annual_payments.id IS 'Surrogate key, system-generated.';
COMMENT ON COLUMN billing.annual_payments.tenant_id IS 'Owning tenant (core.tenants).';
COMMENT ON COLUMN billing.annual_payments.contact_id IS 'Client (crm.contacts); migrated from annualPayments.uID.';
COMMENT ON COLUMN billing.annual_payments.fiscal_year IS 'Fiscal year the figures apply to (four digits); migrated from annualPayments.year.';
COMMENT ON COLUMN billing.annual_payments.currency_code IS 'Currency of the amounts (core.currencies); the tenant default for migrated rows because legacy stores none. [FINANCIAL]';
COMMENT ON COLUMN billing.annual_payments.committed_amount IS 'Amount the client committed to for the year (package), non-negative; 0 for migrated rows (legacy records no commitment). [FINANCIAL]';
COMMENT ON COLUMN billing.annual_payments.paid_amount IS 'Amount paid in the year, non-negative; migrated from annualPayments.payments. [FINANCIAL]';
COMMENT ON COLUMN billing.annual_payments.notes IS 'Finance note about the commitment; user input. NULL = no note.';
COMMENT ON COLUMN billing.annual_payments.legacy_id IS 'Source row id. NULL = created in threeddx3 or the legacy table has no id (annualPayments is keyed by uID + year).';
COMMENT ON COLUMN billing.annual_payments.legacy_source IS 'Legacy table the row was migrated from (annualPayments). NULL = created in threeddx3.';
COMMENT ON COLUMN billing.annual_payments.legacy_key IS 'Composite legacy key (uID:year) when one id is not enough. NULL = not set by the migration, or created in threeddx3.';
COMMENT ON COLUMN billing.annual_payments.created_at IS 'UTC instant the row was created. [AUDIT]';
COMMENT ON COLUMN billing.annual_payments.updated_at IS 'UTC instant of the last change; maintained by trg_annual_payments__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN billing.annual_payments.created_by_user_id IS 'iam.users id of the creator; no FK by design. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN billing.annual_payments.updated_by_user_id IS 'iam.users id of the last editor; no FK by design. NULL = system, migration, or never updated. [AUDIT]';
COMMENT ON CONSTRAINT pk_annual_payments ON billing.annual_payments IS 'Each annual payment row is identified by its surrogate id.';
COMMENT ON CONSTRAINT uq_annual_payments__contact_id__fiscal_year ON billing.annual_payments IS 'One annual figure per client per fiscal year (the ETL upserts on this key); also covers the contact_id FK.';
COMMENT ON CONSTRAINT ck_annual_payments__fiscal_year_range ON billing.annual_payments IS 'Fiscal year is a plausible four-digit year.';
COMMENT ON CONSTRAINT ck_annual_payments__amounts_non_negative ON billing.annual_payments IS 'Committed and paid amounts are never negative.';
COMMENT ON INDEX billing.ix_annual_payments__tenant_id__fiscal_year IS 'Finance report: all clients'' annual figures for one year.';
COMMENT ON INDEX billing.uq_annual_payments__legacy IS 'Every migrated annual figure is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_annual_payments__touch_updated_at BEFORE UPDATE ON billing.annual_payments
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_annual_payments__touch_updated_at ON billing.annual_payments IS 'Sets updated_at and updated_by_user_id on every update.';

-- =============================================================================
-- billing.charge_requests / charge_request_lines   (integrator, 2026-10-14)
-- Legacy CreateOrderCharge (new since March 2026, 12,757 rows): staff record a
-- request to charge a client account for a product, in up to three dated
-- amounts, with how to charge and whom to send the paid/unpaid invoice to.
-- Whether a request row means the money WAS taken is not stated anywhere —
-- TO CONFIRM (OPEN_QUESTIONS); billing.charges remains the record of money
-- actually charged.
-- =============================================================================
CREATE TABLE billing.charge_requests (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    uuid                uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    contact_id          bigint,
    account_reference   varchar(20) NOT NULL,
    requested_by_name   varchar(100) NOT NULL,
    requested_by_user_id bigint,
    requester_email     core.email_address,
    product_description varchar(255),
    description         text NOT NULL,
    charging_method     varchar(255),
    paid_invoice_to     varchar(150),
    unpaid_invoice_to   varchar(150),
    currency_code       core.currency_code,
    requested_at        timestamptz NOT NULL,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_charge_requests PRIMARY KEY (id),
    CONSTRAINT uq_charge_requests__uuid UNIQUE (uuid),
    CONSTRAINT ck_charge_requests__account_reference_not_blank CHECK (btrim(account_reference) <> '')
);
CREATE UNIQUE INDEX uq_charge_requests__legacy ON billing.charge_requests (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;
CREATE INDEX ix_charge_requests__tenant_id__contact_id ON billing.charge_requests (tenant_id, contact_id);
CREATE INDEX ix_charge_requests__tenant_id__requested_at__id ON billing.charge_requests (tenant_id, requested_at, id);
CREATE INDEX ix_charge_requests__requested_by_user_id ON billing.charge_requests (requested_by_user_id) WHERE requested_by_user_id IS NOT NULL;
CREATE INDEX ix_charge_requests__currency_code ON billing.charge_requests (currency_code) WHERE currency_code IS NOT NULL;
COMMENT ON TABLE billing.charge_requests IS 'A request by staff to charge a client account for a product or service, possibly in up to three scheduled amounts (legacy CreateOrderCharge). One row = one request; its amounts and dates are billing.charge_request_lines. Owning module: billing. Whether a request means the charge was executed is TO CONFIRM; executed charges are billing.charges. Contains PII.';
COMMENT ON COLUMN billing.charge_requests.id IS 'Surrogate key. System-generated.';
COMMENT ON COLUMN billing.charge_requests.uuid IS 'Public identifier for APIs. System-generated.';
COMMENT ON COLUMN billing.charge_requests.tenant_id IS 'Owning tenant; row-level security filters on it. Defaults to the session tenant.';
COMMENT ON COLUMN billing.charge_requests.contact_id IS 'Client account to charge, resolved from account_reference (legacy UserAcounts.uID). NULL = the reference matches no migrated client.';
COMMENT ON COLUMN billing.charge_requests.account_reference IS 'Client account number exactly as typed on the request (legacy CreateOrderCharge.account_id, varchar). Kept even when resolved, because the request text refers to it. User input.';
COMMENT ON COLUMN billing.charge_requests.requested_by_name IS 'Staff member named as account owner on the request (legacy account_owner), as typed. User input. [PII]';
COMMENT ON COLUMN billing.charge_requests.requested_by_user_id IS 'Staff user who created the request (legacy created_by_uid, WSacounts.ID). NULL = not recorded (most legacy rows). [AUDIT]';
COMMENT ON COLUMN billing.charge_requests.requester_email IS 'Staff e-mail the request was sent from (legacy email_address). NULL = not given. [PII]';
COMMENT ON COLUMN billing.charge_requests.product_description IS 'What is being charged for, as typed (legacy product_type; 305 distinct values). NULL = not given.';
COMMENT ON COLUMN billing.charge_requests.description IS 'Free-text description of the charge request. User input. [PHI-RISK]';
COMMENT ON COLUMN billing.charge_requests.charging_method IS 'How the charge is to be taken, as typed (legacy charging_method, e.g. card on file). Vocabulary TO CONFIRM. NULL = not given.';
COMMENT ON COLUMN billing.charge_requests.paid_invoice_to IS 'Where the invoice goes once paid (legacy paid_invoice_to, usually a client e-mail). NULL = not given. [PII]';
COMMENT ON COLUMN billing.charge_requests.unpaid_invoice_to IS 'Where the invoice goes while unpaid (legacy unpaid_invoice_to). NULL = not given. [PII]';
COMMENT ON COLUMN billing.charge_requests.currency_code IS 'Currency of the amounts. NULL = not recorded on the legacy request (CreateOrderCharge has no currency column); TO CONFIRM — the client''s default currency is the likely intent. [FINANCIAL]';
COMMENT ON COLUMN billing.charge_requests.requested_at IS 'UTC instant the request was recorded (legacy created_at).';
COMMENT ON COLUMN billing.charge_requests.legacy_id IS 'Source row id (CreateOrderCharge.id). NULL = created in threeddx3.';
COMMENT ON COLUMN billing.charge_requests.legacy_source IS 'Legacy table the row came from (''CreateOrderCharge''). NULL = created in threeddx3.';
COMMENT ON COLUMN billing.charge_requests.legacy_key IS 'Composite legacy key. NULL = legacy_id alone identifies the source row, or created in threeddx3.';
COMMENT ON COLUMN billing.charge_requests.created_at IS 'UTC instant the row was created. System-generated. [AUDIT]';
COMMENT ON COLUMN billing.charge_requests.updated_at IS 'UTC instant of the last change. System-generated. [AUDIT]';
COMMENT ON COLUMN billing.charge_requests.created_by_user_id IS 'User who created the row; no FK (audit history must survive the user). NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN billing.charge_requests.updated_by_user_id IS 'User who last changed the row; no FK. NULL = system or migration. [AUDIT]';
COMMENT ON CONSTRAINT pk_charge_requests ON billing.charge_requests IS 'Each charge request has one surrogate key.';
COMMENT ON CONSTRAINT uq_charge_requests__uuid ON billing.charge_requests IS 'The public uuid identifies exactly one request.';
COMMENT ON CONSTRAINT ck_charge_requests__account_reference_not_blank ON billing.charge_requests IS 'A charge request always names the account it is for.';
COMMENT ON INDEX billing.uq_charge_requests__legacy IS 'Every migrated request is traceable to one CreateOrderCharge row and cannot be loaded twice.';
COMMENT ON INDEX billing.ix_charge_requests__tenant_id__contact_id IS 'All charge requests of a client (account billing history).';
COMMENT ON INDEX billing.ix_charge_requests__tenant_id__requested_at__id IS 'Keyset pagination of requests by time.';
COMMENT ON INDEX billing.ix_charge_requests__requested_by_user_id IS 'Requests raised by one staff member; supports the FK to iam.users.';
COMMENT ON INDEX billing.ix_charge_requests__currency_code IS 'Supports the FK to core.currencies.';
CREATE TRIGGER trg_charge_requests__touch_updated_at BEFORE UPDATE ON billing.charge_requests
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_charge_requests__touch_updated_at ON billing.charge_requests IS 'Keeps updated_at and updated_by_user_id current on every change.';

CREATE TABLE billing.charge_request_lines (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    charge_request_id   bigint NOT NULL,
    line_no             smallint NOT NULL,
    amount              core.money_amount NOT NULL,
    charge_on           date NOT NULL,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    CONSTRAINT pk_charge_request_lines PRIMARY KEY (id),
    CONSTRAINT uq_charge_request_lines__request__line UNIQUE (charge_request_id, line_no),
    CONSTRAINT ck_charge_request_lines__line_no_range CHECK (line_no BETWEEN 1 AND 12),
    CONSTRAINT ck_charge_request_lines__amount_non_negative CHECK (amount >= 0),
    CONSTRAINT fk_charge_request_lines__charge_request_id FOREIGN KEY (charge_request_id)
        REFERENCES billing.charge_requests (id) ON DELETE CASCADE ON UPDATE NO ACTION
);
CREATE UNIQUE INDEX uq_charge_request_lines__legacy ON billing.charge_request_lines (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;
CREATE INDEX ix_charge_request_lines__tenant_id__charge_on ON billing.charge_request_lines (tenant_id, charge_on);
COMMENT ON TABLE billing.charge_request_lines IS 'One scheduled amount of a charge request: amount and the date it is to be charged (legacy CreateOrderCharge.charge_1..3 / charge_date_1..3). Child of billing.charge_requests; removed with it. Owning module: billing.';
COMMENT ON COLUMN billing.charge_request_lines.id IS 'Surrogate key. System-generated.';
COMMENT ON COLUMN billing.charge_request_lines.tenant_id IS 'Owning tenant (same as the request). Defaults to the session tenant.';
COMMENT ON COLUMN billing.charge_request_lines.charge_request_id IS 'The request this scheduled amount belongs to.';
COMMENT ON COLUMN billing.charge_request_lines.line_no IS 'Position in the schedule: 1 = first charge (legacy charge_1), 2, 3 …; up to 12 for future instalment plans.';
COMMENT ON COLUMN billing.charge_request_lines.amount IS 'Amount to charge on charge_on, in the request''s currency (billing.charge_requests.currency_code). Non-negative. [FINANCIAL]';
COMMENT ON COLUMN billing.charge_request_lines.charge_on IS 'Calendar date the amount is to be charged (legacy charge_date_n).';
COMMENT ON COLUMN billing.charge_request_lines.legacy_id IS 'Source row id (CreateOrderCharge.id of the request). NULL = created in threeddx3.';
COMMENT ON COLUMN billing.charge_request_lines.legacy_source IS 'Legacy table (''CreateOrderCharge''). NULL = created in threeddx3.';
COMMENT ON COLUMN billing.charge_request_lines.legacy_key IS 'Which legacy column pair the line came from (''charge_1'' … ''charge_3''). NULL = created in threeddx3.';
COMMENT ON COLUMN billing.charge_request_lines.created_at IS 'UTC instant the row was created. System-generated. [AUDIT]';
COMMENT ON COLUMN billing.charge_request_lines.created_by_user_id IS 'User who created the row; no FK. NULL = system or migration. [AUDIT]';
COMMENT ON CONSTRAINT pk_charge_request_lines ON billing.charge_request_lines IS 'Each scheduled amount has one surrogate key.';
COMMENT ON CONSTRAINT uq_charge_request_lines__request__line ON billing.charge_request_lines IS 'A request has at most one amount per schedule position.';
COMMENT ON CONSTRAINT ck_charge_request_lines__line_no_range ON billing.charge_request_lines IS 'Schedule positions run 1 to 12.';
COMMENT ON CONSTRAINT ck_charge_request_lines__amount_non_negative ON billing.charge_request_lines IS 'A scheduled charge amount is never negative; refunds are separate charges.';
COMMENT ON CONSTRAINT fk_charge_request_lines__charge_request_id ON billing.charge_request_lines IS 'A scheduled amount belongs to one request; CASCADE because a line has no meaning without its request and carries no executed money.';
COMMENT ON INDEX billing.uq_charge_request_lines__legacy IS 'Every migrated line is traceable to its CreateOrderCharge column pair and cannot be loaded twice.';
COMMENT ON INDEX billing.ix_charge_request_lines__tenant_id__charge_on IS 'Upcoming scheduled charges by date (what is due to be charged today).';
